#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with
# libvirt-outside-of-docker installed with default options, without a mount at /run/libvirt, after the entrypoint and
# the start check ran once.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=/dev/null
source "$(dirname "$0")/helpers.sh"

check "virsh is on PATH and reports a version" virsh --version
check "virt-install is installed by default" virt-install --version
check "qemu-img is not installed by default" bash -c '! command -v qemu-img'
check "no libvirt daemon and no QEMU system emulator is installed" no_daemon_installed
check "the entrypoint and the start check exist and are executable" test -x "${LOD_ALIGN}" -a -x "${LOD_CHECK}"
check "LIBVIRT_DEFAULT_URI is qemu:///system" test "${LIBVIRT_DEFAULT_URI:-}" = qemu:///system
check "nothing exists at /run/libvirt: the feature declares no mount and creates nothing there" \
  bash -c '! test -e /run/libvirt'
check "the entrypoint recorded this start as unchanged, with no socket" \
  bash -c "test \"\$(record_field result)\" = unchanged && record_field reason | grep -q 'no host socket is mounted'"
check "the start record is not writable by the remote user unless that user is root" \
  bash -c "test \"\$(id -u)\" = 0 || ! test -w ${LOD_RECORD}"
check "the start check exits zero and names the mount to add" check_reports_no_socket
check "the image holds no libvirt-in-docker" bash -c '! test -e /usr/local/share/libvirt-in-docker'

reportResults
